#include<stdio.h>
#include<math.h>

bool flag[1000000];

void sieve() {
    long long p = (long long)sqrt(1000000.0);
    flag[0] = flag[1] = true; // 0 and 1 are not prime
    for (long long i = 2; i <= p; i++) {
        if (!flag[i]) {
            for (long long j = i * i; j < 1000000; j += i) {
                flag[j] = true;
            }
        }
    }
}

int main(void) {
    long long n, count;
    sieve(); // Precompute primes
    while (scanf("%lld", &n) != EOF) {
        if (n <= 1) count = 0;
        else {
            count = 1; // Counting the prime number 2
            for (long long i = 3; i <= n; i += 2) {
                if (!flag[i]) count++;
            }
        }
        printf("%lld\n", count);
    }
    return 0;
}

