void sieve() {
    flag[0] = flag[1] = false; // 0 and 1 are not prime numbers
    int p = (int)sqrt(1000000.0);
    for (int i = 2; i <= p; i++) {
        if (flag[i]) {
            for (int j = i * i; j < 1000000; j += i) {
                flag[j] = false; // Mark multiples of i as non-prime
            }
        }
    }
}

int main(void) {
    int n, count;
    sieve();
    while (scanf("%d", &n) != EOF) {
        if (n <= 1) {
            printf("0\n");
            continue; // Early exit for small values
        }
        count = 0; // Change count to 0 for counting primes
        for (int i = 2; i <= n && i < 1000000; i++) { // Start from 2
            if (flag[i]) count++;
        }
        printf("%d\n", count);
    }
    return 0;
}

